input.newString:
function update(dt){
  dt=Math.min(dt,.033);
  world+=speed*dt;
  if(playing){
    score+=speed*dt*1.8;
    speed=Math.min(20,11+score/650);
    lane+=(targetLane-lane)*Math.min(1,dt*12);
    if(jumpV||jump>0){jump+=jumpV*dt;jumpV-=34*dt;if(jump<0){jump=0;jumpV=0}}
    if(slide>0)slide-=dt;
    if(inv>0)inv-=dt;
    if(shield>0)shield-=dt;
    for(const o of objects)o.z-=speed*dt;
    objects=objects.filter(o=>o.z>-8);
    while(objects.length<14){let max=20;for(const o of objects)max=Math.max(max,o.z);spawn(max+11+Math.random()*8)}
    for(const o of objects){
      if(o.z<5&&o.z>-1.5&&Math.abs(o.lane-lane)<.42){
        if(o.type==='coin'||o.type==='gem'){
          coins+=o.type==='gem'?5:1;o.z=-10;
          for(let i=0;i<7;i++)particles.push({x:lane,y:jump,z:0,vx:(Math.random()-.5)*3,vy:Math.random()*3,vz:Math.random()*3,life:1,color:o.type==='gem'?'#70f5ff':'#ffd64a'});
        }else if(o.type==='barrier'&&jump<1.15){hit()}else if(o.type==='rock'&&slide<=0&&jump<.65){hit()}
      }
    }
  }
  for(let i=0;i<particles.length;i++){const p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vz+=dt}
  particles=particles.filter(p=>p.life>0);
  document.getElementById('score').textContent=Math.floor(score);
  document.getElementById('coins').textContent=coins;
}

